   "quote": "ClearTrail Plus supports the AAC Bluetooth audio codec on compatible phones, so its published Bluetooth version can be treated as evidence for that specific audio-compression capability.",
   "label": "unknown",
   "fact_ids": [
    "cleartrail.plus.bluetooth_version"
   ],
   "reason": "The catalogue specifies Bluetooth version 5.3 but does not list supported audio codecs."
  },
  {
   "quote": "The plastic used in the enclosure of ClearTrail Plus contains at least sixty percent post-consumer recycled material by weight, excluding the electronic components and the external retail packaging.",
   "label": "unknown",
   "fact_ids": [],
   "reason": "The catalogue contains no facts about recycled material content in the enclosure."
  },
  {
   "quote": "With all port covers closed, ClearTrail Plus is permitted to remain immersed in fresh water at a depth of one metre for a full hour under the manufacturer's stated laboratory allowance.",
   "label": "contradicted",
   "fact_ids": [
    "cleartrail.plus.immersion_duration"
   ],
   "reason": "The catalogue specifies an immersion duration of 30 minutes, not a full hour."
  },
  {
   "quote": "The official India catalogue price of ClearTrail Plus will drop by INR 300 during January 2027, with that future reduction applying before shipping to purchases from the brand itself.",
