   ],
   "reason": "The catalogue confirms that an invoice is required for the standard India manufacturer warranty."
  },
  {
   "quote": "For wired digital audio specifically, the USB-C connector on ClearTrail Plus does provide an audio-input path, regardless of the fact that the connector also serves charging.",
   "label": "supported",
   "fact_ids": [
    "cleartrail.plus.usb_audio"
   ],
   "reason": "The catalogue confirms that wired digital audio through the USB-C port is supported (true)."
  },
  {
   "quote": "An original invoice is unnecessary when claiming the standard India manufacturer warranty for ClearTrail Plus, provided the buyer says the purchase came from an authorized seller.",
